#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
cd "$(dirname "$0")/.."
if [[ ! -t 0 ]]; then
  warn "Wizard potřebuje interaktivní terminál (ne ! v Claude Code). Spusť: cd $(pwd) && ./scripts/setup.sh"
  exit 1
fi

banner "Kalendáře e-shop: Sanity, Stripe a Cloudflare"

stage "Sanity: projekt"
say "Založíš Sanity projekt, odkud e-shop načítá produkty."
open_url "https://www.sanity.io/manage"
step "Přihlas se (např. přes GitHub) a klikni na 'Create new project'."
step "Pojmenuj ho třeba 'kalendar-eshop'. Pokud se ptá na dataset, nech 'production' jako Public."
step "Na stránce projektu zkopíruj 'Project ID' (8 znaků, např. ab12cd34)."
ask SANITY_PROJECT_ID "Vlož Project ID:"
write_env SANITY_PROJECT_ID "$SANITY_PROJECT_ID"
write_env SANITY_DATASET "production"
ENV_FILE=studio/.env write_env SANITY_STUDIO_PROJECT_ID "$SANITY_PROJECT_ID"
export SANITY_STUDIO_PROJECT_ID="$SANITY_PROJECT_ID"  # sanity.cli.ts reads it
pause

stage "Sanity: přihlášení CLI, dataset a CORS"
say "Sanity CLI teď otevře prohlížeč, přihlas se stejným účtem."
pnpm --dir studio exec sanity login
note "Vytvářím veřejný dataset 'production' (pokud už existuje, nevadí)…"
pnpm --dir studio exec sanity dataset create production --visibility public || note "dataset už nejspíš existuje, pokračuju"
pnpm --dir studio exec sanity cors add http://localhost:3333 --credentials || note "CORS pro localhost:3333 už nejspíš existuje"
pause

stage "Sanity: nasazení Studia a první produkty"
say "Nasadím Studio na <název>.sanity.studio. CLI se zeptá na název (hostname), vymysli si ho."
pnpm --dir studio run deploy
say ""
step "Otevři URL Studia, kterou CLI vypsalo výše (https://<název>.sanity.studio)."
step "Přidej 2–3 produkty: Název, klikni 'Generate' u URL, Cena v Kč, obrázek a pak 'Publish'."
note "Bez publikovaných produktů bude e-shop prázdný."
pause "Až budeš mít produkty publikované, stiskni Enter."

stage "Sanity: token pro zápis objednávek"
say "Webhook ukládá zaplacené objednávky do Sanity, k tomu potřebuje token s právem zápisu."
open_url "https://www.sanity.io/manage/project/$SANITY_PROJECT_ID/api"
step "Najdi sekci 'Tokens' a klikni na 'Add API token'."
step "Name: eshop-orders, Permissions: Editor, a pak 'Save'."
step "Token se zobrazí jen jednou, hned ho zkopíruj."
ask_secret SANITY_WRITE_TOKEN "Vlož token:"
write_env SANITY_WRITE_TOKEN "$SANITY_WRITE_TOKEN"
pause

stage "Stripe: testovací klíč"
say "Platby poběží v testovacím režimu, žádné skutečné peníze."
open_url "https://dashboard.stripe.com/test/apikeys"
step "Přihlas se nebo založ účet. Aktivovat účet pro testovací režim nemusíš."
step "U 'Secret key' klikni 'Reveal test key' a zkopíruj ho (začíná sk_test_)."
ask_secret STRIPE_SECRET_KEY "Vlož secret key:"
[[ "$STRIPE_SECRET_KEY" == sk_test_* ]] || warn "klíč nezačíná sk_test_, zkontroluj, že nejsi v live režimu"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
note "Lokálně to teď jede: pnpm dev → http://localhost:3000"
pause

stage "Cloudflare: nasazení"
say "Wrangler otevře prohlížeč a přihlásí tě k Cloudflare účtu."
pnpm exec wrangler login
if confirm "Nasadit e-shop na Cloudflare Workers (worker 'kalendar-eshop')?"; then
  pnpm run deploy
  note "Nahrávám tajné hodnoty do Workeru…"
  printf '%s' "$SANITY_PROJECT_ID" | pnpm exec wrangler secret put SANITY_PROJECT_ID
  printf '%s' "$STRIPE_SECRET_KEY" | pnpm exec wrangler secret put STRIPE_SECRET_KEY
  printf '%s' "$SANITY_WRITE_TOKEN" | pnpm exec wrangler secret put SANITY_WRITE_TOKEN
  step "Hotovo, e-shop běží na https://kalendar-eshop.<tvůj-subdomain>.workers.dev (URL je ve výpisu deploye výše)."
else
  SKIPPED+=("Cloudflare deploy: pnpm run deploy, pak wrangler secret put SANITY_PROJECT_ID a STRIPE_SECRET_KEY")
fi
pause

stage "Stripe: webhook pro objednávky"
say "Zaregistruju u Stripe webhook, který po zaplacení uloží objednávku do Sanity."
step "Vlož URL nasazeného e-shopu (z předchozího kroku, např. https://kalendar-eshop.xyz.workers.dev)."
ask SHOP_URL "URL e-shopu:"
SHOP_URL="${SHOP_URL%/}"
[[ "$SHOP_URL" == http*://* ]] || SHOP_URL="https://$SHOP_URL"
write_env SHOP_URL "$SHOP_URL"
WEBHOOK_URL="$SHOP_URL/api/stripe-webhook"
existing=$(curl -sS -u "$STRIPE_SECRET_KEY:" "https://api.stripe.com/v1/webhook_endpoints?limit=100" \
  | node -e 'const d=JSON.parse(require("fs").readFileSync(0));process.stdout.write((d.data||[]).some(e=>e.url===process.argv[1])?"yes":"")' "$WEBHOOK_URL" || true)
if [[ -n "$existing" ]]; then
  note "Webhook pro $WEBHOOK_URL už existuje, přeskakuju (secret už byl nahrán dřív)."
elif confirm "Vytvořit Stripe webhook pro $WEBHOOK_URL?"; then
  resp=$(curl -sS -u "$STRIPE_SECRET_KEY:" https://api.stripe.com/v1/webhook_endpoints \
    -d url="$WEBHOOK_URL" -d "enabled_events[]=checkout.session.completed" || true)
  WEBHOOK_SECRET=$(printf '%s' "$resp" | node -e 'try{process.stdout.write(JSON.parse(require("fs").readFileSync(0)).secret||"")}catch{}')
  if [[ "$WEBHOOK_SECRET" == whsec_* ]]; then
    printf '%s' "$WEBHOOK_SECRET" | pnpm exec wrangler secret put STRIPE_WEBHOOK_SECRET
    note "Lokálně: stripe listen --forward-to localhost:3000/api/stripe-webhook a whsec_… dej do .env jako STRIPE_WEBHOOK_SECRET"
  else
    warn "Stripe webhook se nepodařilo vytvořit: $(printf '%s' "$resp" | node -e 'try{process.stdout.write(JSON.parse(require("fs").readFileSync(0)).error.message)}catch{process.stdout.write("neznámá chyba")}')"
    SKIPPED+=("Stripe webhook: spusť wizard znovu, nebo ho přidej v Developers → Webhooks")
  fi
else
  SKIPPED+=("Stripe webhook: Developers → Webhooks → $WEBHOOK_URL, událost checkout.session.completed, pak wrangler secret put STRIPE_WEBHOOK_SECRET")
fi
pause

stage "GitHub: repozitář pro portfolio"
say "Vytvořím veřejný GitHub repozitář a pushnu kód. CI tam pustí build s kontrolou route tree, typecheck a testy."
if ! gh auth status >/dev/null 2>&1; then
  say "gh CLI není přihlášené, spouštím gh auth login…"
  gh auth login
fi
if confirm "Udělat první commit a vytvořit veřejný repozitář 'kalendar-eshop'?"; then
  git add -A
  git commit -m "Initial commit: Kalendáře e-shop" || note "nic nového ke commitu"
  gh repo create kalendar-eshop --public --source . --push
else
  SKIPPED+=("GitHub: git commit a gh repo create kalendar-eshop --public --source . --push")
fi
pause

finish
say "Lokální vývoj: pnpm dev (e-shop) a pnpm studio (Sanity Studio na :3333)"
say "Testovací karta: 4242 4242 4242 4242, libovolné budoucí datum a CVC"
}

run_wizard "$@"; exit
